insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('NG', 'default', 'Nigeria reference chart of accounts', '{}'::jsonb, true, 'companies', array['NG-CAMA-BS', 'NG-CAMA-IS']::text[], null, 'There is no legal chart of accounts in Nigeria. Companies and Allied Matters Act 2020, s. 378(1) requires the financial statements every company''s directors prepare under s. 377 to comply with the First Schedule to the Act "so far as applicable" for their form and content, and with the accounting standards the Financial Reporting Council of Nigeria lays down under the Financial Reporting Council of Nigeria Act 2011 — the FRC having adopted the IFRS Accounting Standards for public interest entities and the IFRS for SMEs Standard for other entities. Neither prescribes a nominal ledger, only a balance sheet and profit and loss account format (First Schedule, Section C, Format 1, the format this chart''s statements follow) and a set of recognition and measurement standards. This chart is original: four digits, blocked so that each range reaches one line of the First Schedule Format 1 balance sheet or profit and loss account, carrying the accounts a Nigerian company actually keeps — VAT recoverable and payable, the amount due to or from the Service, VAT paid to the Nigeria Customs Service on import, Pay As You Earn, Pension Reform Act and National Housing Fund contributions, the Nigeria Social Insurance Trust Fund and Industrial Training Fund levies, withholding tax credit notes and withholding tax payable, and Companies Income Tax and Development Levy apart from VAT.', 'cama-2020')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

