insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('NG', 'NG-P-EX', 'Purchase, exempt', '{}'::jsonb, 'A purchase of a supply section 185 exempts — land, a lease of a building, money or securities, a government licence, and the other items of that section.', 'percent', 0, 'purchase', 'exempt', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 185(1). An exempt purchase carries no input tax at all.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null),
  ('NG', 'NG-P-IMP', 'Purchase, import of goods, VAT paid to the Nigeria Customs Service', '{}'::jsonb, 'Goods imported into Nigeria, VAT on the import value paid to the Nigeria Customs Service before the goods are cleared, the ordinary case.', 'percent', 7.5, 'purchase', 'import', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 149: "the value of imported taxable supply […] shall be the amount which is equal to the price of the taxable supply imported plus (a) taxes, duties and other charges levied either outside or by reason of importation into Nigeria, other than VAT imposed under this Act; and (b) costs by way of commission, packing, transport and insurance up to the port or point of entry." Section 155(3): "an importer of taxable goods shall, before clearing those goods, pay to the Service the VAT on the goods." In practice the Nigeria Customs Service collects the VAT at the border on the Service''s behalf, against the same Single Goods Declaration as customs duty. The tax is owed to Customs and not to the foreign supplier, so the tax lands on 2150 — the account the payment to Customs settles — rather than being added to the amount credited to the supplier''s account, mirroring the same shape packs/sa/taxes.json uses for its own import tax.', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null),
  ('NG', 'NG-P-NR', 'Purchase, supplier is a small business exempt from charging VAT', '{}'::jsonb, 'A purchase from a supplier whose gross turnover does not exceed ₦100,000,000 a year and whose total fixed assets do not exceed ₦250,000,000 — a "small business", not required to register, charge VAT or file returns, unless it has opted out.', 'percent', 0, 'purchase', 'not_subject', date '2026-01-01', null, 'Nigeria Tax Administration Act 2025, s. 22(4): "the provision of subsection (1) of this section [monthly VAT returns] shall not apply to a small business"; s. 22(9) carves companies engaged in petroleum operations back out of the exemption. "Small Business" is defined in s. 202: "a business that earns gross turnover of ₦100,000,000.00 or less per annum with total fixed assets not more than ₦250,000,000.00[,] provided that any business providing professional services shall not be classified as a small business." No tax is charged because the supplier is outside the VAT system for as long as it stays under the threshold and has not opted in under s. 22(5); not reported on any box of the return.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ntaa-2025', null, null, null, null),
  ('NG', 'NG-P-SR', 'Purchase, standard-rated, input tax deductible', '{}'::jsonb, 'A standard-rated purchase of goods, services or fixed assets used for the purpose of making taxable supplies.', 'percent', 7.5, 'purchase', 'domestic', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 155(4): "Input tax incurred by a registered person on any taxable supply, including services and fixed assets made to such person, may be deducted from the tax payable by the person on its taxable supplies at the end of the tax period in which the supply occurred, but only to the extent that the input tax was incurred for the purpose of consumption, use or supply in the course of making taxable supplies." The proviso to s. 155(4)(a) restricts the deduction, where a purchase serves both taxable and non-taxable supplies, to the proportion relating to the taxable ones — **this pack applies no such apportionment**: the socle has no column for a partly-deductible tax, the gap packs/sa/tax_report.json records for Saudi Arabia''s own proportional-deduction rule. Section 155(4)(b) allows the deduction within five years of the end of the tax period the input tax was incurred in.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null),
  ('NG', 'NG-P-ZR', 'Purchase, zero-rated', '{}'::jsonb, 'A purchase of a supply section 186 rates at zero percent — no tax was charged, and none is deducted because none was paid.', 'percent', 0, 'purchase', 'domestic', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 186. The supplier charges no VAT on a zero-rated supply, so a purchase of one carries no input tax to deduct; it is reported so that the VAT payable of s. 22(3) of the Nigeria Tax Administration Act — "the input tax paid, output tax collected and Value Added Tax payable in respect of all taxable supplies in the preceding month" — is stated against the whole of what was bought and not only against the taxed share of it.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null),
  ('NG', 'NG-S-EX', 'Sale, exempt', '{}'::jsonb, 'A supply section 185 exempts outright — among them oil and gas exports, crude petroleum oil and feed gas, land or a building, money and securities, a government licence, baby products, locally manufactured sanitary towels, pads or tampons, and assistive devices and disability-related products.', 'percent', 0, 'sale', 'exempt', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 185(1): "the following supplies are exempt from the VAT imposed under Chapter Six of this Act — (a) oil and gas exports; (b) crude petroleum oil and feed gas for all processed gas; (c) goods purchased for use in humanitarian donor funded projects […]; (d) baby products; (e) locally manufactured sanitary towels, pads or tampons; (f) military hardware […]; (g) shared passenger road-transport service; (h) purchase, hire, rental or lease of tractors, ploughs and other equipment used for agricultural purposes[;] (i) supplies consumed by an approved entity in the export processing or free trade zones […]; (j) goods or services supplied to a diplomatic mission […]; (k) plays and performances conducted by educational institutions as part of learning; (l) land or building including interest in land or building; (m) money, stakes or securities including interest in money or securities; (n) Government licences; and (o) Assistive devices and disability-related products including hearing aids, wheelchairs, and braille materials." Note that oil and gas exports are exempt and not zero-rated — the exporter charges no VAT and deducts none of its input tax on them, unlike an ordinary export under NG-S-ZR-EXPORT.', null, null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null),
  ('NG', 'NG-S-SR', 'Sale, standard-rated, VAT 7.5%', '{}'::jsonb, 'A taxable supply of goods, services or an incorporeal deemed to take place in Nigeria under section 145 of the Nigeria Tax Act, that is neither zero-rated under section 186 nor exempt under section 185.', 'percent', 7.5, 'sale', 'domestic', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 147: "Subject to the provisions of Part IX of this Chapter, VAT shall be charged on the value of all taxable supplies at the rate of 7.5%." Section 148(1)(a) fixes the base: for a money consideration, the value of the supply is the amount which, with the VAT added, equals the consideration — the base is therefore the price net of the tax itself, as this tax''s `base` posting carries it. The rate is unchanged from the Value Added Tax Act as amended by the Finance Act 2019, which raised it from 5% to 7.5% with effect from 1 February 2020; the Nigeria Tax Act re-enacts the same figure and repeals that Act with effect from 1 January 2026 (Nigeria Tax Act 2025, s. 195, Ninth Schedule).', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null),
  ('NG', 'NG-S-ZR-DOM', 'Sale, zero-rated, domestic supply of a listed essential good or service', '{}'::jsonb, 'A domestic supply of one of the goods or services section 186 rates at zero percent — basic food items, medical and pharmaceutical products, educational books and materials, fertilisers and other listed agricultural inputs, live cattle, goats, sheep and poultry, electricity generated for or transmitted on the national grid, medical services and equipment, and tuition from nursery to tertiary level.', 'percent', 0, 'sale', 'domestic', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 186(a)–(m) and (q): basic food items (defined at s. 188 as an agriculture- or aquatic-based staple food — cereals, roots, meat, fish, milk, salt and similar, raw or semi-processed), all medical and pharmaceutical products including medicinal herbal products, educational books and materials, fertilisers, locally produced agricultural chemicals, veterinary medicine and animal feeds, live cattle, goats, sheep and poultry, agricultural seeds and seedlings, electricity generated by a GENCO and supplied to the National Grid or the Nigeria Bulk Electricity Trading Company, electricity transmitted by the Transmission Company of Nigeria to a DISCO, medical services, tuition relating to nursery, primary, secondary or tertiary education, and medical equipment. Subject to Eleventh Schedule, paragraph 1 (petroleum products, renewable energy equipment, CNG, LPG and other gaseous hydrocarbons), whose charging and collection the Minister may suspend or start by an order in the Official Gazette — this pack carries no tax code for those items; see packs/ng/README.md.', null, null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null),
  ('NG', 'NG-S-ZR-EXPORT', 'Sale, zero-rated, exported goods, services or incorporeal property', '{}'::jsonb, 'Goods exported from Nigeria (other than oil and gas), and services or incorporeal property exported to a person outside Nigeria.', 'percent', 0, 'sale', 'export', date '2026-01-01', null, 'Nigeria Tax Act 2025, s. 186: "the following taxable supplies are charged to VAT at the rate of zero percent — (n) exported goods excluding oil and gas; (o) exported services; (p) exported incorporeal property." Oil and gas exports are not zero-rated under this paragraph: section 185(1)(a) exempts them instead — see NG-S-EX. `vat_category` is left null: this pack declares no `einvoicing.profile`, so BT-151 is not a term of any invoice this pack''s companies issue, and Nigeria carries no VATEX-style register of its own reason codes this pack''s research could find (packs/packs.md § "What a tax says on the invoice").', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'nta-2025', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
