    ('NG-P-EX', 'invoice', 'base', 100, null, '7', array['7']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-P-EX', 'credit_note', 'base', 100, null, '7', array['7']::text[], -100, 'NG-VAT-RETURN', 10),
    ('NG-P-IMP', 'invoice', 'base', 100, null, '8', array['8']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-P-IMP', 'invoice', 'tax', 100, '1140', '8', array['8']::text[], 100, 'NG-VAT-RETURN', 20),
    ('NG-P-IMP', 'invoice', 'tax', -100, '2150', null, null, 100, null, 30),
    ('NG-P-IMP', 'credit_note', 'base', 100, null, '8', array['8']::text[], -100, 'NG-VAT-RETURN', 10),
    ('NG-P-IMP', 'credit_note', 'tax', 100, '1140', '8', array['8']::text[], -100, 'NG-VAT-RETURN', 20),
    ('NG-P-IMP', 'credit_note', 'tax', -100, '2150', null, null, 100, null, 30),
    ('NG-P-SR', 'invoice', 'base', 100, null, '5', array['5']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-P-SR', 'invoice', 'tax', 100, '1140', '5', array['5']::text[], 100, 'NG-VAT-RETURN', 20),
    ('NG-P-SR', 'credit_note', 'base', 100, null, '5', array['5']::text[], -100, 'NG-VAT-RETURN', 10),
    ('NG-P-SR', 'credit_note', 'tax', 100, '1140', '5', array['5']::text[], -100, 'NG-VAT-RETURN', 20),
    ('NG-P-ZR', 'invoice', 'base', 100, null, '6', array['6']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-P-ZR', 'credit_note', 'base', 100, null, '6', array['6']::text[], -100, 'NG-VAT-RETURN', 10),
    ('NG-S-EX', 'invoice', 'base', 100, null, '3', array['3']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-S-EX', 'credit_note', 'base', 100, null, '3', array['3']::text[], -100, 'NG-VAT-RETURN', 10),
    ('NG-S-SR', 'invoice', 'base', 100, null, '1', array['1']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-S-SR', 'invoice', 'tax', 100, '2200', '1', array['1']::text[], 100, 'NG-VAT-RETURN', 20),
    ('NG-S-SR', 'credit_note', 'base', 100, null, '1', array['1']::text[], -100, 'NG-VAT-RETURN', 10),
    ('NG-S-SR', 'credit_note', 'tax', 100, '2200', '1', array['1']::text[], -100, 'NG-VAT-RETURN', 20),
    ('NG-S-ZR-DOM', 'invoice', 'base', 100, null, '2', array['2']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-S-ZR-DOM', 'credit_note', 'base', 100, null, '2', array['2']::text[], -100, 'NG-VAT-RETURN', 10),
    ('NG-S-ZR-EXPORT', 'invoice', 'base', 100, null, '2', array['2']::text[], 100, 'NG-VAT-RETURN', 10),
    ('NG-S-ZR-EXPORT', 'credit_note', 'base', 100, null, '2', array['2']::text[], -100, 'NG-VAT-RETURN', 10)
  ) as v (tax_code, document_kind, posting_type, factor_percent, account_code,
