insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('NG', 'NG-VAT-RETURN', 'VAT return', array['month']::declaration_period[], 'month'::declaration_period, date '2026-01-01', null, 'Nigeria Tax Administration Act 2025, s. 22(1): "A taxable person shall, in respect of Value Added Tax (VAT), with or without a notice and whether or not an economic activity has taken place, submit a return to the Service in the prescribed form, on or before the 21st day of the following month"; s. 22(3): "the returns shall contain the input tax paid, output tax collected and Value Added Tax payable in respect of all taxable supplies in the preceding month." A tax period is one calendar month, and no cadence but monthly exists for it — unlike Belgium or Ireland, nothing in the Act lets a taxable person ask for a longer one. **The return is filed on the Service''s own portal, TaxPro-Max, which has accepted no manual VAT return since June 2021** (Federal Inland Revenue Service Information Circular on e-filing, June 2021); the most recent public specimen of a printed form this pack''s research could find is Form VAT 002, whose worked example still carries the 5% rate the Finance Act 2019 superseded and whose figures are stated inclusive of VAT in a way TaxPro-Max''s own sales-schedule upload (net value entered, VAT computed at 7.5%) does not appear to reproduce. Rather than transcribe a paper form''s box numbers as if they were what the portal shows today, this pack numbers its own boxes against the statutory description of s. 22(3) — output tax, input tax, VAT payable — the way packs/sa/tax_report.json numbers a return that is itself a screen and not a printed form. A reviewer who files a real return on TaxPro-Max should check the boxes against what the portal shows.', true,'day_of_month_after_period'::filing_deadline_rule, 21, null, 'Nigeria Tax Administration Act 2025, s. 22(1), quoted above. Section 49(1) sets the same day for payment: "every person shall make payment of tax due on or before the due date of filing", and s. 154(4), for VAT collected, withheld or self-accounted by a government body or an appointed collector, gives the fourteenth day instead — a different obligation on a different person, which this pack does not model (packs/ng/README.md).', 'ntaa-2025', null)
