  ('NG', 'NG-VAT-RETURN', '1', 'base', 'Standard-rated sales', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 147: taxable supplies at the standard rate of 7.5%, stated net of the tax itself under s. 148(1)(a).', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '1', 'tax', 'Output VAT on standard-rated sales', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Administration Act 2025, s. 22(3): the output tax collected on taxable supplies.', 'ntaa-2025'),
  ('NG', 'NG-VAT-RETURN', '2', 'base', 'Zero-rated sales', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 186: exported goods, services and incorporeal property, and the domestic supplies the section lists — basic food, medical and pharmaceutical products, educational materials, agricultural inputs, electricity supplied to or by the national grid, medical services and equipment, and tuition.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '3', 'base', 'Exempt sales', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 185(1): oil and gas exports, crude petroleum oil and feed gas, land and buildings, money and securities, government licences, and the other items of that section.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '4', 'total', 'Total output tax', '{}'::jsonb, 50, null, array['1:tax']::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Administration Act 2025, s. 22(3), the "output tax collected" component of the return.', 'ntaa-2025'),
  ('NG', 'NG-VAT-RETURN', '5', 'base', 'Standard-rated domestic purchases', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 155(4): input tax deductible on a taxable supply, including services and fixed assets, to the extent used in making taxable supplies.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '5', 'tax', 'Deductible input VAT on standard-rated domestic purchases', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 155(4), the deductible input tax of a standard-rated domestic purchase.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '6', 'base', 'Zero-rated purchases', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'A purchase of a supply section 186 rates at zero percent, carrying no input tax to deduct.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '7', 'base', 'Exempt purchases', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'A purchase of a supply section 185 exempts, carrying no VAT at all.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '8', 'base', 'Imports of goods', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 149: the value of an imported taxable supply, plus non-VAT duties and charges and the costs of getting it to the port or point of entry.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '8', 'tax', 'VAT paid to the Nigeria Customs Service on import, deductible', '{}'::jsonb, 110, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 155(3): an importer pays the VAT on taxable goods to the Service, in practice through the Nigeria Customs Service, before clearing them; the tax is then deductible under s. 155(4) like any other input tax.', 'nta-2025'),
  ('NG', 'NG-VAT-RETURN', '9', 'total', 'Total input tax deductible', '{}'::jsonb, 120, null, array['5:tax', '8:tax']::text[], '{}'::text[], null, null, false, false, null, 'Nigeria Tax Administration Act 2025, s. 22(3), the "input tax paid" component of the return.', 'ntaa-2025'),
  ('NG', 'NG-VAT-RETURN', '10', 'total', 'VAT payable, or refundable', '{}'::jsonb, 130, null, array['4']::text[], array['9']::text[], null, null, false, false, null, 'Nigeria Tax Act 2025, s. 155(1): where output VAT exceeds input VAT the excess is remitted to the Service; where input VAT exceeds output VAT the taxable person carries the excess forward as a credit against subsequent months, or under s. 155(2) may request a refund. This pack applies no floor at zero: a negative figure here is the credit or the refund s. 155 describes.', 'nta-2025')
