values
  ('NG-CAMA-BS', 'NG', 'default', 'Statement of financial position', 'balance_sheet', 'NG-CAMA', date '2026-01-01', null, 'Companies and Allied Matters Act 2020, s. 377(2)(b) requires "the balance sheet or balance sheet as at the last day of the year" among the financial statements the directors prepare; s. 378(1) requires it to comply with the First Schedule to the Act "so far as applicable" and with the accounting standards the Financial Reporting Council of Nigeria lays down. The lines below follow the First Schedule, Section C, Balance Sheet Formats, Format 1 — a vertical format, headed A to M — summarised to the level of this chart''s own account blocks; each heading below names the paragraph of Format 1 it carries.', 'cama-2020'),
  ('NG-CAMA-IS', 'NG', 'default', 'Statement of profit or loss', 'income_statement', 'NG-CAMA', date '2026-01-01', null, 'Companies and Allied Matters Act 2020, s. 377(2)(c) requires "a profit and loss account […] for the year" among the financial statements the directors prepare; s. 378(1) requires it to comply with the First Schedule to the Act "so far as applicable". The lines below follow the First Schedule, Section C, Profit and Loss Account Formats, Format 1 (the function-of-expense format), summarised to the level of this chart''s own account blocks.', 'cama-2020')
