  rounding_method        = excluded.rounding_method,
  cash_rounding_unit     = excluded.cash_rounding_unit,
  fx_gain_code           = excluded.fx_gain_code,
  fx_loss_code           = excluded.fx_loss_code,
  asset_disposal_gain_code        = excluded.asset_disposal_gain_code,
  asset_disposal_loss_code        = excluded.asset_disposal_loss_code,
  asset_disposal_proceeds_code    = excluded.asset_disposal_proceeds_code,
  asset_disposal_value_code       = excluded.asset_disposal_value_code,
  tax_payable_code                = excluded.tax_payable_code,
  tax_receivable_code             = excluded.tax_receivable_code,
  opening_entry_label             = excluded.opening_entry_label,
  vat_period_default              = excluded.vat_period_default;

update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Nigeria Tax Act 2025, s. 152(1): a taxable person making a taxable supply "shall maintain a sequential invoice numbering" and furnish the purchaser with a VAT invoice. The section asks the numbering to run in sequence and says nothing of a hole in it, which is why `numbering` is `sequential` and not gapless; the pattern in `number_format` is one series a business may choose and not one the Act prints.',
  numbering_source_key          = 'nta-2025',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Nigeria Tax Act 2025, s. 146(1): "a taxable supply shall be deemed to take place at the time an invoice or receipt is issued by the supplier, or where goods are delivered or made available for use, or payment is due to or received by the supplier in respect of that supply, whichever occurs first." That is a three-way earliest test — invoice, delivery, payment — and the closed vocabulary of this field has no value naming all three at once. `earliest_of_delivery_or_payment` is the nearest of the five and misses only the case where an invoice is issued ahead of both delivery and payment, which s. 146(1) would still make the tax point; docs/international.md records the same gap this pack found for Saudi Arabia and Vietnam under an equivalent three-way rule.',
  tax_point_source_key          = 'nta-2025',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Electronic invoicing exists in Nigeria and this pack still leaves all four fields above empty, for the reason packs/sa/ and packs/mx/ leave them empty: the FIRS Merchant-Buyer Solution (MBS), live since 1 August 2025, is a clearance platform a seller transmits an invoice to before it reaches the buyer, built to the Service''s own schema and exchanged over the Service''s API — not an EN 16931 profile any brick of packages/formats writes, and not a four-corner network a `party_scheme`/`vat_scheme` pair of ISO 6523 identifiers addresses (Nigeria carries no entry in the Peppol electronic address scheme list). Nigeria Tax Act 2025, s. 152(4), gives the statutory hook: "the Service may direct any taxable person who makes taxable supplies to adopt the use of electronic invoice, provided that it gives a notice of, at least 30 days". Under that hook the Service required every taxable person with an annual turnover of at least ₦5 billion to onboard to the MBS by 1 November 2025 (extended from 1 August 2025), covering business-to-business, business-to-government and business-to-consumer supplies; the pilot ran from November 2024. No instrument this pack''s research could find sets a date for taxpayers below that turnover, so `mandatory_from` would be a date nobody has fixed for most companies a reader installs this pack for. `obligation` is left out for the same reason `packs/sa/pack.json` leaves it out: the schema refuses `mandatory` without `mandatory_from`, and there is no profile to hang either on. docs/international.md carries the rest, including Nigeria Tax Act 2025, s. 157, and Nigeria Tax Administration Act 2025, s. 23, which give the Service a second and wider power to deploy an Electronic Fiscal System for recording and reporting supplies, by regulations this pack''s research found none yet published.',
  einvoice_source_key           = 'mbs-rollout',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = null
 where country = 'NG';
